//! Local web server so a phone or tablet on the same network can use EDCH.
//!
//! Security model: the server is off by default. Every request needs the secret token
//! (random, generated by the app) that the QR code carries. Scanning the QR code opens
//! /pair?t=TOKEN, which stores the token (HttpOnly cookie + local storage) and opens the app;
//! knowing the PC's IP and port is not enough. "New code" replaces the token, which
//! disconnects every paired device.
//!
//! The desktop UI stays the source of truth: it publishes a JSON snapshot of its state
//! (remote_publish), phones long-poll /api/state, and phone actions (wishlist edits)
//! come back to the desktop as "remote-action" events.

use serde::Serialize;
use std::io::Read;
use std::net::UdpSocket;
use std::sync::{Arc, Condvar, Mutex, MutexGuard};
use std::thread;
use std::time::Duration;
use tauri::{AppHandle, Emitter, Manager, State};
use tiny_http::{Header, Method, Request, Response, Server, StatusCode};

const BODY_LIMIT: u64 = 4 << 20;
const LONG_POLL: Duration = Duration::from_secs(25);

#[derive(Default)]
struct Shared {
    token: Mutex<String>,
    /// (version, JSON state) published by the desktop UI.
    snapshot: Mutex<(u64, String)>,
    changed: Condvar,
    server: Mutex<Option<Arc<Server>>>,
}

#[derive(Default)]
pub struct RemoteState {
    inner: Arc<Shared>,
}

#[derive(Serialize)]
pub struct RemoteInfo {
    port: u16,
    addresses: Vec<String>,
}

fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|e| e.into_inner())
}

/// Comparison whose time doesn't depend on where the strings differ.
fn same_secret(a: &str, b: &str) -> bool {
    if a.len() != b.len() || a.is_empty() {
        return false;
    }
    a.bytes().zip(b.bytes()).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

fn percent_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'+' {
            out.push(b' ');
        } else if b == b'%' && i + 3 <= bytes.len() {
            let hex = std::str::from_utf8(&bytes[i + 1..i + 3]).ok().and_then(|h| u8::from_str_radix(h, 16).ok());
            match hex {
                Some(v) => {
                    out.push(v);
                    i += 2;
                }
                None => out.push(b'%'),
            }
        } else {
            out.push(b);
        }
        i += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

fn query_param(query: &str, key: &str) -> Option<String> {
    query.split('&').find_map(|pair| {
        let (k, v) = pair.split_once('=').unwrap_or((pair, ""));
        (k == key).then(|| percent_decode(v))
    })
}

fn cookie_token(req: &Request) -> Option<String> {
    req.headers()
        .iter()
        .filter(|h| h.field.equiv("Cookie"))
        .flat_map(|h| h.value.as_str().split(';').map(|c| c.trim().to_string()).collect::<Vec<_>>())
        .find_map(|c| c.strip_prefix("edch_t=").map(|v| v.to_string()))
}

fn respond(req: Request, status: u16, content_type: &str, body: Vec<u8>, extra: &[(&str, String)]) {
    let mut response = Response::from_data(body).with_status_code(StatusCode(status));
    let base = [
        ("Content-Type", content_type.to_string()),
        ("Cache-Control", "no-store".to_string()),
        ("X-Content-Type-Options", "nosniff".to_string()),
        ("Referrer-Policy", "no-referrer".to_string()),
        ("X-Frame-Options", "DENY".to_string()),
    ];
    for (k, v) in base.iter().map(|(k, v)| (*k, v.clone())).chain(extra.iter().map(|(k, v)| (*k, v.clone()))) {
        if let Ok(h) = Header::from_bytes(k.as_bytes(), v.as_bytes()) {
            response.add_header(h);
        }
    }
    let _ = req.respond(response);
}

fn json<T: Serialize>(req: Request, value: &T) {
    let body = serde_json::to_vec(value).unwrap_or_else(|_| b"null".to_vec());
    respond(req, 200, "application/json; charset=utf-8", body, &[]);
}

/// Page returned by /pair: the browser keeps the secret (cookie + local storage, for browsers
/// that drop the cookie) and then opens the app with a fresh, same-origin navigation.
fn pair_page(token: &str) -> String {
    format!(
        r#"<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EDCH</title>
<style>body{{font-family:system-ui,sans-serif;background:#0a0c0f;color:#e7e9ec;display:grid;place-items:center;min-height:100vh;margin:0}}a{{color:#ff7a18}}</style></head>
<body><p><a href="/">EDCH</a></p><script>try{{localStorage.setItem("edch.remoteToken","{token}")}}catch(e){{}}location.replace("/");</script></body></html>"#
    )
}

fn header_token(req: &Request) -> Option<String> {
    req.headers()
        .iter()
        .find(|h| h.field.equiv("X-EDCH-Token"))
        .map(|h| h.value.as_str().trim().to_string())
}

fn read_body(req: &mut Request) -> Result<String, String> {
    let mut body = String::new();
    req.as_reader()
        .take(BODY_LIMIT)
        .read_to_string(&mut body)
        .map_err(|e| e.to_string())?;
    Ok(body)
}

fn handle(app: AppHandle, shared: Arc<Shared>, mut req: Request) {
    let url = req.url().to_string();
    let (path, query) = url.split_once('?').unwrap_or((url.as_str(), ""));
    let path = path.to_string();
    let query = query.to_string();
    let token = lock(&shared.token).clone();

    // Pairing: the QR code's URL. A valid token is handed to the browser; a stale one sends the
    // phone to the app, which explains that the code must be scanned again.
    if path == "/pair" {
        let given = query_param(&query, "t").unwrap_or_default();
        if same_secret(&given, &token) {
            let cookie = format!("edch_t={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=31536000");
            respond(req, 200, "text/html; charset=utf-8", pair_page(&token).into_bytes(), &[("Set-Cookie", cookie)]);
        } else {
            respond(req, 302, "text/plain", b"Expired".to_vec(), &[("Location", "/#expired".to_string())]);
        }
        return;
    }

    let authorised = cookie_token(&req)
        .into_iter()
        .chain(header_token(&req))
        .any(|t| same_secret(&t, &token));
    let is_get = *req.method() == Method::Get;

    // The app's own files carry no data of the commander: they load without the secret, so a
    // phone that isn't paired gets a proper explanation instead of a bare error page.
    if !path.starts_with("/api/") {
        if !is_get {
            respond(req, 405, "text/plain", b"Method not allowed".to_vec(), &[]);
            return;
        }
        let rel = path.trim_start_matches('/');
        let rel = if rel.is_empty() { "index.html" } else { rel };
        let rel = percent_decode(rel);
        if rel.contains("..") {
            respond(req, 400, "text/plain", b"Bad path".to_vec(), &[]);
            return;
        }
        match app.asset_resolver().get(rel.clone()) {
            Some(asset) => {
                let mime = asset.mime_type().to_string();
                respond(req, 200, &mime, asset.bytes().to_vec(), &[]);
            }
            None => respond(req, 404, "text/plain", b"Not found".to_vec(), &[]),
        }
        return;
    }

    if is_get && path == "/api/hello" {
        json(req, &serde_json::json!({ "remote": true, "paired": authorised, "version": env!("CARGO_PKG_VERSION") }));
        return;
    }
    if !authorised {
        respond(req, 401, "application/json", br#"{"error":"not paired"}"#.to_vec(), &[]);
        return;
    }

    match (is_get, path.as_str()) {

        (true, "/api/state") => {
            let since: u64 = query_param(&query, "since").and_then(|v| v.parse().ok()).unwrap_or(0);
            let guard = lock(&shared.snapshot);
            let (guard, _) = shared
                .changed
                .wait_timeout_while(guard, LONG_POLL, |snap| snap.0 <= since)
                .unwrap_or_else(|e| e.into_inner());
            let body = format!(
                "{{\"version\":{},\"state\":{}}}",
                guard.0,
                if guard.1.is_empty() { "null" } else { guard.1.as_str() }
            );
            drop(guard);
            respond(req, 200, "application/json; charset=utf-8", body.into_bytes(), &[]);
        }

        (false, "/api/http") => {
            let reply = read_body(&mut req).and_then(|body| {
                let v: serde_json::Value = serde_json::from_str(&body).map_err(|e| e.to_string())?;
                let method = v["method"].as_str().unwrap_or("GET").to_string();
                let url = v["url"].as_str().unwrap_or("").to_string();
                let payload = v["body"].as_str().map(|s| s.to_string());
                let content_type = v["contentType"].as_str().map(|s| s.to_string());
                crate::blocking_http(&method, &url, payload.as_deref(), content_type.as_deref())
            });
            match reply {
                Ok(r) => json(req, &r),
                Err(e) => respond(req, 502, "text/plain; charset=utf-8", e.into_bytes(), &[]),
            }
        }

        (false, "/api/action") => match read_body(&mut req).and_then(|b| serde_json::from_str::<serde_json::Value>(&b).map_err(|e| e.to_string())) {
            Ok(value) => {
                let _ = app.emit("remote-action", value);
                respond(req, 204, "text/plain", Vec::new(), &[]);
            }
            Err(e) => respond(req, 400, "text/plain; charset=utf-8", e.into_bytes(), &[]),
        },

        (true, "/api/options") => match crate::list_option_files() {
            Ok(files) => json(req, &files),
            Err(e) => respond(req, 500, "text/plain; charset=utf-8", e.into_bytes(), &[]),
        },

        (true, "/api/option") => {
            let folder = query_param(&query, "folder").unwrap_or_default();
            let name = query_param(&query, "name").unwrap_or_default();
            match crate::read_option_file(folder, name) {
                Ok(text) => respond(req, 200, "text/plain; charset=utf-8", text.into_bytes(), &[]),
                Err(e) => respond(req, 404, "text/plain; charset=utf-8", e.into_bytes(), &[]),
            }
        }

        _ => respond(req, 405, "text/plain", b"Method not allowed".to_vec(), &[]),
    }
}

/// LAN addresses to put in the QR code (the one used for outgoing traffic first).
#[tauri::command]
pub fn remote_addresses() -> Vec<String> {
    let mut out = Vec::new();
    // Connecting a UDP socket sends nothing; it only picks the outgoing interface.
    for target in ["192.168.1.1:80", "10.255.255.255:80", "8.8.8.8:80"] {
        if let Ok(sock) = UdpSocket::bind("0.0.0.0:0") {
            if sock.connect(target).is_ok() {
                if let Ok(addr) = sock.local_addr() {
                    let ip = addr.ip();
                    if !ip.is_loopback() && !ip.is_unspecified() && !is_tailscale(&ip) {
                        let s = ip.to_string();
                        if !out.contains(&s) {
                            out.push(s);
                        }
                    }
                }
            }
        }
    }
    out
}

/// Tailscale gives every device an address in 100.64.0.0/10 (CGNAT range).
fn is_tailscale(ip: &std::net::IpAddr) -> bool {
    match ip {
        std::net::IpAddr::V4(v4) => {
            let o = v4.octets();
            o[0] == 100 && (o[1] & 0xC0) == 64
        }
        std::net::IpAddr::V6(_) => false,
    }
}

/// This PC's Tailscale address, if Tailscale is running. 100.100.100.100 is Tailscale's own
/// resolver: only the Tailscale interface routes to it, so the socket picks that interface.
#[tauri::command]
pub fn remote_tailscale() -> Option<String> {
    let sock = UdpSocket::bind("0.0.0.0:0").ok()?;
    sock.connect("100.100.100.100:53").ok()?;
    let ip = sock.local_addr().ok()?.ip();
    is_tailscale(&ip).then(|| ip.to_string())
}

#[tauri::command]
pub fn remote_start(app: AppHandle, state: State<'_, RemoteState>, token: String, port: u16) -> Result<RemoteInfo, String> {
    if token.len() < 32 || !token.chars().all(|c| c.is_ascii_alphanumeric()) {
        return Err("Jeton invalide".into());
    }
    let shared = state.inner.clone();
    *lock(&shared.token) = token;
    // Already running on this port: just keep it (the token was updated above).
    if let Some(server) = lock(&shared.server).as_ref() {
        if server.server_addr().to_ip().map(|a| a.port()) == Some(port) {
            return Ok(RemoteInfo { port, addresses: remote_addresses() });
        }
        server.unblock();
    }
    let server = Arc::new(Server::http(("0.0.0.0", port)).map_err(|e| format!("Port {port} indisponible : {e}"))?);
    *lock(&shared.server) = Some(server.clone());
    let loop_shared = shared.clone();
    thread::spawn(move || loop {
        let still_current = lock(&loop_shared.server).as_ref().map(|s| Arc::ptr_eq(s, &server)).unwrap_or(false);
        if !still_current {
            break;
        }
        match server.recv() {
            Ok(req) => {
                let app = app.clone();
                let shared = loop_shared.clone();
                thread::spawn(move || handle(app, shared, req));
            }
            Err(_) => break,
        }
    });
    Ok(RemoteInfo { port, addresses: remote_addresses() })
}

#[tauri::command]
pub fn remote_stop(state: State<'_, RemoteState>) {
    let shared = state.inner.clone();
    if let Some(server) = lock(&shared.server).take() {
        server.unblock();
    }
    lock(&shared.token).clear();
    shared.changed.notify_all();
}

#[tauri::command]
pub fn remote_publish(app: AppHandle, state: String) {
    let shared = app.state::<RemoteState>().inner.clone();
    let mut snap = lock(&shared.snapshot);
    snap.0 += 1;
    snap.1 = state;
    drop(snap);
    shared.changed.notify_all();
}

#[tauri::command]
pub fn remote_qr(text: String) -> Result<String, String> {
    let code = qrcode::QrCode::new(text.as_bytes()).map_err(|e| e.to_string())?;
    Ok(code
        .render::<qrcode::render::svg::Color>()
        .min_dimensions(240, 240)
        .quiet_zone(true)
        .dark_color(qrcode::render::svg::Color("#000000"))
        .light_color(qrcode::render::svg::Color("#ffffff"))
        .build())
}
